SELECT percentile_cont(0.95) within GROUP (ORDER BY (vital_signs_systolic_pressure - vital_signs_diastolic_pressure) / NULLIF(vital_signs_heart_rate, 0)) AS percentile_95 FROM chartevents JOIN icu_stays ON chartevents.subject_id = icu_stays.subject_id AND chartevents.hadm_id = icu_stays.hadm_id AND chartevents.stay_id = icu_stays.stay_id WHERE (icu_stays.outtime - icu_stays.intime) <= 48 AND (vital_signs_systolic_pressure - vital_signs_diastolic_pressure) / NULLIF(vital_signs_heart_rate, 0) > 0;